import { Injectable, inject, signal } from '@angular/core';
import { CanActivateFn, Router } from '@angular/router';

/**
 * One selectable element of the auditorium as booked: a single seat, or a couch that
 * covers `column` and `column + 1`.
 */
export interface BookedItem {
  row: number;
  column: number;
  couch: boolean;
}

/** The booking in progress, kept in `sessionStorage` (spec 3.1). */
export interface Booking {
  screeningId: number;
  /** Selected seats and couches, in row then column order. */
  items: BookedItem[];
}

const STORAGE_KEY = 'cinescope.booking';

/** Price of one element in PLN (spec 5.4). A couch is priced as a whole. */
export function priceOf(item: BookedItem): number {
  if (item.couch) {
    return 89;
  }
  if (item.row <= 5) {
    return 25;
  }
  if (item.row <= 10) {
    return 32;
  }
  return 39;
}

/** Total price of the items in PLN. */
export function totalPrice(items: readonly BookedItem[]): number {
  return items.reduce((sum, item) => sum + priceOf(item), 0);
}

/** Formats an amount as `25.00 PLN`. */
export function formatPrice(amount: number): string {
  return `${amount.toFixed(2)} PLN`;
}

/** Identifies a booked element; the same key the seat map uses for its elements. */
export function itemKey(item: BookedItem): string {
  return `${item.couch ? 'couch' : 'seat'}-${item.row}-${item.column}`;
}

function sortItems(items: readonly BookedItem[]): BookedItem[] {
  return [...items].sort((a, b) => a.row - b.row || a.column - b.column);
}

function readStoredBooking(): Booking | null {
  try {
    const raw = sessionStorage.getItem(STORAGE_KEY);
    return raw ? (JSON.parse(raw) as Booking) : null;
  } catch {
    return null;
  }
}

/** Holds the booking in progress and mirrors it into `sessionStorage`. */
@Injectable({ providedIn: 'root' })
export class BookingStore {
  private readonly state = signal<Booking | null>(readStoredBooking());

  /** The booking in progress, or `null`. */
  readonly booking = this.state.asReadonly();

  /** Keeps the booking in progress when it belongs to the screening; otherwise starts an empty one. */
  open(screeningId: number): void {
    if (this.state()?.screeningId !== screeningId) {
      this.write({ screeningId, items: [] });
    }
  }

  /** Replaces the selected items of the booking in progress. */
  setItems(items: readonly BookedItem[]): void {
    const current = this.state();
    if (current) {
      this.write({ ...current, items: sortItems(items) });
    }
  }

  clear(): void {
    this.write(null);
  }

  private write(booking: Booking | null): void {
    this.state.set(booking);
    if (booking) {
      sessionStorage.setItem(STORAGE_KEY, JSON.stringify(booking));
    } else {
      sessionStorage.removeItem(STORAGE_KEY);
    }
  }
}

/**
 * Lets a route open only while the booking in progress belongs to the screening in the
 * `id` parameter and holds at least one seat; otherwise redirects to `/`.
 */
export const bookingInProgressGuard: CanActivateFn = (route) => {
  const booking = inject(BookingStore).booking();
  const allowed =
    booking !== null &&
    booking.screeningId === Number(route.paramMap.get('id')) &&
    booking.items.length > 0;
  return allowed || inject(Router).createUrlTree(['/']);
};

import { Component, computed, effect, inject, input, resource } from '@angular/core';
import { MatButtonModule } from '@angular/material/button';
import { Router } from '@angular/router';
import { BookedItem, BookingStore, formatPrice, itemKey, priceOf, totalPrice } from '../booking';
import { CinemaApi } from '../cinema-api';
import { Movie, Screening } from '../models';

interface SummaryData {
  movie: Movie;
  screening: Screening;
}

interface SummaryLine {
  key: string;
  item: BookedItem;
  seat: string;
  price: string;
}

@Component({
  selector: 'app-summary',
  imports: [MatButtonModule],
  templateUrl: './summary.html',
  styleUrl: './summary.scss',
})
export class Summary {
  private readonly api = inject(CinemaApi);
  private readonly bookings = inject(BookingStore);
  private readonly router = inject(Router);

  /** Bound from the `id` route parameter. */
  readonly id = input.required<string>();

  protected readonly data = resource({
    params: () => this.id(),
    loader: async ({ params: id }): Promise<SummaryData> => {
      const screening = await this.api.getScreening(Number(id));
      const movie = await this.api.getMovie(screening.movieId);
      return { movie, screening };
    },
  });

  protected readonly lines = computed<SummaryLine[]>(() =>
    (this.bookings.booking()?.items ?? []).map((item) => ({
      key: itemKey(item),
      item,
      seat: item.couch ? `Couch ${item.column}-${item.column + 1}` : `${item.column}`,
      price: formatPrice(priceOf(item)),
    })),
  );

  protected readonly total = computed(
    () => `Total: ${formatPrice(totalPrice(this.bookings.booking()?.items ?? []))}`,
  );

  constructor() {
    effect(() => {
      if (this.data.error()) {
        this.router.navigate(['/']);
      }
    });
  }

  /** Takes one seat or couch out of the booking; opens the seat map when none is left. */
  protected remove(key: string): void {
    const remaining = (this.bookings.booking()?.items ?? []).filter((item) => itemKey(item) !== key);
    this.bookings.setItems(remaining);
    if (remaining.length === 0) {
      this.toSeats();
    }
  }

  protected back(): void {
    this.toSeats();
  }

  protected confirm(): void {
    this.router.navigate(['/screenings', this.id(), 'checkout']);
  }

  private toSeats(): void {
    this.router.navigate(['/screenings', this.id(), 'seats']);
  }
}

